use xiom.io;

use xiom.string;
fn first[T](items: &Vec[T]) -> Option[T] {
  return items.get(0);
}

fn is_empty[T](items: &Vec[T]) -> Bool {
  return items.len() == 0;
}

fn count[T](items: &Vec[T]) -> Int {
  return items.len();
}

fn main() -> Int {
  let nums: Vec[Int] = Vec[Int].new();
  nums.push(42);

  let words: Vec[Str] = Vec[Str].new();
  words.push("hello");

  io.println(string.int_to_str(count(&nums)));
  io.println(string.int_to_str(count(&words)));
  io.println(string.bool_to_str(is_empty(&nums)));

  let empty_vec: Vec[Int] = Vec[Int].new();
  io.println(string.bool_to_str(is_empty(&empty_vec)));
  return 0;
}
